fun FlowContent.orderForm(invalid: Boolean = false) {
    val field = no.lotek.Lt.field(id = "$codename$", required = no.lotek.RequiredMarker.SYMBOL, error = true, invalid = invalid)
    form {
        id = "$order_form$"
        attributes["novalidate"] = ""
        ltField {
            label { lt(field.label); +"Codename" }
            input { lt(no.lotek.Lt.input(type = no.lotek.InputType.TEXT), field.control); name = "$codename$"; required = true }
            p { lt(no.lotek.Lt.errorText(), field.error); +"Enter a codename." }
        }
        button { lt(no.lotek.Lt.button()); type = ButtonType.submit; +"Order the job" }
    }
}

data class Part(val key: String, val title: String, val text: String)

fun FlowContent.claimTabs(
    parts: List<Part> = listOf(
        Part("claim", "Claim", "Claim AV-2079-0481 was filed on 4 March 2079."),
        Part("attachments", "Attachments", "Three attachments have been uploaded."),
    ),
) {
    val tabs = no.lotek.Lt.tabs(id = "$claim_tabs$", keys = parts.map { it.key }, label = "Parts of the claim")
    ltTabs {
        id = "$claim_tabs$"
        ul {
            lt(tabs.list)
            parts.zip(tabs.tabs).forEach { (part, tab) -> li { a { lt(tab); +part.title } } }
        }
        for ((i, part) in parts.withIndex()) {
            section {
                lt(tabs.panels[i])
                h2 { lt(tabs.headings[i]); +part.title }
                p { +part.text }
            }
        }
    }
}

data class Fault(val field: String, val message: String)

fun FlowContent.orderForm(faults: List<Fault> = emptyList()) {
    val summary = no.lotek.Lt.errorSummary(count = faults.size, id = "$errors$", titleId = "$errors_title$")
    val fixer = no.lotek.Lt.field(id = "$fixer$", invalid = faults.any { it.field == "$fixer$" })
    form {
        attributes["novalidate"] = ""
        ltErrorSummary {
            lt(summary.host)
            h2 {
                lt(summary.title)
                if (faults.isNotEmpty()) +(if (faults.size == 1) "The form has one error" else "The form has $${faults.size} errors")
            }
            ul {
                lt(no.lotek.Lt.list())
                for (fault in faults) li { a(href = "#$${fault.field}") { +fault.message } }
            }
        }
        label { lt(fixer.label); +"Fixer's address" }
        input { lt(no.lotek.Lt.input(type = no.lotek.InputType.EMAIL), fixer.control); name = "$fixer$" }
        button { lt(no.lotek.Lt.button()); +"Order the job" }
    }
}

fun FlowContent.actionsMenu() {
    val menu = no.lotek.Lt.popover(id = "$actions$", placement = no.lotek.PopoverPlacement.BOTTOM_END)
    ltPopover {
        id = "$menu$"
        lt(menu.host)
        button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), menu.trigger); type = ButtonType.button; +"Actions" }
        ul {
            lt(menu.panel)
            li { button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); type = ButtonType.button; +"Mark LDG-117 returned" } }
            li { button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); type = ButtonType.button; +"Charge the late fee" } }
        }
    }
}

data class Breaker(val code: String, val name: String)

fun FlowContent.breakerSearch(
    breakers: List<Breaker> = listOf(Breaker("crowbar", "Crowbar"), Breaker("needle", "Needle")),
) {
    val search = no.lotek.Lt.suggestion(id = "$breaker$", keys = breakers.map { it.code })
    ltSuggestion {
        id = "$breaker_search$"
        label { lt(search.label); +"Breaker" }
        input { lt(search.control); name = "$breaker$" }
        ul {
            lt(search.list)
            breakers.zip(search.options).forEach { (breaker, option) -> li { lt(option); +breaker.name } }
        }
        p { lt(search.empty); +"No matches" }
        span { lt(search.status) }
    }
}

fun FlowContent.cancelJob() {
    val box = no.lotek.Lt.dialog(titleId = "$confirm_title$")
    button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.DANGER)); id = "$open_confirm$"; type = ButtonType.button; +"Cancel the job" }
    dialog {
        lt(box.dialog)
        id = "$confirm$"
        h2 { lt(box.title); +"Cancel job 222-0481?" }
        div {
            lt(box.body)
            p { +"The crew keeps the advance. This cannot be undone." }
        }
        form {
            lt(box.footer)
            attributes["method"] = "dialog"
            button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY)); value = "keep"; +"Keep the job" }
            button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.DANGER)); value = "cancel"; +"Cancel the job" }
        }
    }
}

fun FlowContent.sessionWarning() {
    val session = no.lotek.Lt.sessionTimeout(titleId = "$session_title$", warnAt = 1500, expiresAt = 1800)
    ltSessionTimeout {
        lt(session.host)
        dialog {
            lt(session.dialog)
            h2 { lt(session.title); +"Your session is ending" }
            p {
                lt(session.text)
                +"Your session on the Lattice ends in "
                span { lt(session.count) }
                +". Unsaved routes will be lost."
            }
            span { lt(session.live) }
            form {
                lt(session.actions)
                attributes["method"] = "dialog"
                button { lt(no.lotek.Lt.button(), session.extend); +"Stay connected" }
                button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), session.logout); +"Log out" }
            }
        }
    }
}
